import React, { useState } from 'react';

interface Image {
  id: number;
  src: string;
  alt: string;
  title: string;
}

const ImageGallery = () => {
  const images: Image[] = [
    { id: 1, src: 'image1.jpg', alt: 'Mountain view', title: 'Mountain' },
    { id: 2, src: 'image2.jpg', alt: 'Beach sunset', title: 'Beach' },
    { id: 3, src: 'image3.jpg', alt: 'Forest path', title: 'Forest' }
  ];

  const [selectedImage, setSelectedImage] = useState<Image | null>(null);

  const selectImage = (image: Image) => {
    setSelectedImage(image);
  };

  return (
    <div>
      <div>
        {images.map((image) => (
          <img
            key={image.id}
            src={image.src}
            alt={image.alt}
            title={image.title}
            onClick={() => selectImage(image)}
          />
        ))}
      </div>
      <div>
        {/* Conditionally render selected image title and larger image here */}
      </div>
    </div>
  );
};

export default ImageGallery;
